# SPDX-License-Identifier: MIT
# Trusted short-I/O driver for binhex/zlib fixtures (takeover root). It makes
# deterministic inputs, feeds or drains FIFOs while the side shell is blocked in
# read(2)/write(2) (observed through /proc/PID/wchan) and signals it, and checks
# captured outputs. It never runs the candidate.
import bz2, gzip, hashlib, json, lzma, os, signal, sys, time, zlib


def plain(n):
    out, i = bytearray(), 0
    while len(out) < n:
        out += hashlib.sha256(b'%d' % i).digest() * (1 + i % 3) + bytes([i % 256]) * (i % 97)
        i += 1
    return bytes(out[:n])


def wchan(pid):
    try:
        with open('/proc/%d/wchan' % pid) as handle:
            return handle.read().strip()
    except OSError:
        return '?'


def blocked(pid, want, seconds=3.0):
    deadline = time.monotonic() + seconds
    while time.monotonic() < deadline:
        if wchan(pid) == want:
            return 1
        time.sleep(0.002)
    return 0


def read_page(fd):
    got = b''
    while len(got) < 4096:
        part = os.read(fd, 4096 - len(got))
        if not part:
            break
        got += part
    return got


def main():
    cmd, a = sys.argv[1], sys.argv[2:]
    if cmd == 'make':
        data = plain(1 << 20)
        small = data[:200000]
        files = {'plain.bin': data, 'small.bin': small, 'plain.hex': data.hex().encode(), 'small.hex': small.hex().encode(),
                 'plain.gz': gzip.compress(data, mtime=0), 'plain.zlib': zlib.compress(data),
                 'plain.xz': lzma.compress(data), 'plain.lzma': lzma.compress(data, format=lzma.FORMAT_ALONE),
                 'plain.bz2': bz2.compress(data)}
        raw = zlib.compressobj(6, zlib.DEFLATED, -15)
        files['plain.deflate'] = raw.compress(data) + raw.flush()
        for name, blob in files.items():
            with open(name, 'wb') as handle:
                handle.write(blob)
    elif cmd == 'feed':
        # feed PID FIFO FILE N: signal N times while PID blocks reading FIFO, then
        # write FILE in 999-byte chunks with pauses (short reads) and close.
        pid, fifo, path, n = int(a[0]), a[1], a[2], int(a[3])
        fd = os.open(fifo, os.O_WRONLY)
        seen = 0
        for _ in range(n):
            seen += blocked(pid, 'pipe_read')
            os.kill(pid, signal.SIGUSR1)
            time.sleep(0.05)
        data = open(path, 'rb').read()
        for k in range(0, len(data), 999):
            os.write(fd, data[k:k + 999])
            time.sleep(0.001)
        os.close(fd)
        print('feed signals=%d blocked-in-read=%d' % (n, seen))
    elif cmd == 'drain':
        # drain PID FIFO OUT N: each round signal while PID blocks writing a full
        # FIFO (EINTR), free one page, signal again mid-write (short count); then
        # read everything into OUT.
        pid, fifo, out, n = int(a[0]), a[1], a[2], int(a[3])
        fd = os.open(fifo, os.O_RDONLY)
        got, seen = bytearray(), 0
        for _ in range(n):
            seen += blocked(pid, 'pipe_write')
            os.kill(pid, signal.SIGUSR1)
            time.sleep(0.02)
            seen += blocked(pid, 'pipe_write')
            got += read_page(fd)
            seen += blocked(pid, 'pipe_write')
            os.kill(pid, signal.SIGUSR1)
            time.sleep(0.02)
        while True:
            part = os.read(fd, 65536)
            if not part:
                break
            got += part
        os.close(fd)
        with open(out, 'wb') as handle:
            handle.write(got)
        print('drain signals=%d blocked-in-write=%d/%d' % (2 * n, seen, 3 * n))
    elif cmd == 'check':
        # check LABEL OUT WANT [SKIP]: OUT equals WANT from byte SKIP on
        got, want = open(a[1], 'rb').read(), open(a[2], 'rb').read()[int(a[3]) if len(a) > 3 else 0:]
        print('%s output=%s' % (a[0], 'match' if got == want else 'differ(%d/%d)' % (len(got), len(want))))
    elif cmd == 'prefix':
        # prefix LABEL OUT WANT N: OUT is exactly the first N bytes of WANT
        got, want, n = open(a[1], 'rb').read(), open(a[2], 'rb').read(), int(a[3])
        print('%s output=%s' % (a[0], 'prefix-%d' % n if got == want[:n] else 'differ(%d)' % len(got)))
    elif cmd == 'gunzip':
        got, want = open(a[1], 'rb').read(), open(a[2], 'rb').read()
        try:
            ok = gzip.decompress(got) == want
        except (OSError, EOFError):
            ok = False
        print('%s gzip-decodes-to-input=%s' % (a[0], 'yes' if ok else 'no'))
    elif cmd in ('log', 'count'):
        # log LABEL LOG SYSCALL: injected replies and whether the call was made again;
        # count: the same with the exact number of notified calls
        calls = injected = 0
        for line in open(a[1]):
            r = json.loads(line)
            if r.get('syscall') == a[2]:
                calls += 1
                injected += r.get('reply') != 'continue'
        if cmd == 'log':
            print('%s %s-injected=%d retried=%s' % (a[0], a[2], injected, 'yes' if calls > injected else 'no'))
        else:
            print('%s %s-calls=%s injected=%d' % (a[0], a[2], 'many' if calls > 50 else calls, injected))
    elif cmd == 'reads':
        # reads LABEL LOG MIN: at least MIN read(2) calls on stdin were made
        calls = sum(1 for line in open(a[1]) if json.loads(line).get('syscall') == 'read')
        print('%s short-reads=%s' % (a[0], 'yes' if calls >= int(a[2]) else 'no(%d)' % calls))
    else:
        raise SystemExit('unknown ' + cmd)


main()

